UPDATE site_content SET payload = '{"meta":{"title":"91SkylineWorks — Building Doctor | Structural Repair Guwahati","description":"Building problems? We diagnose first, then fix. Waterproofing, retrofitting, PU injection, NDT & structural repair in Guwahati & Northeast India. Free inspection."},"company":{"name":"91SkylineWorks","fullName":"91SkylineWorks Private Limited","tagline":"Your home in Guwahati — safer, drier, stronger.","license":"Building safety & retrofitting — Guwahati","logo":"/images/logo.png"},"hero":{"eyebrow":"Building doctor · Guwahati","headline":"Your building has a problem. We find out why.","subheadline":"Water leaking through a concrete terrace? Cracks in a column? Damp walls every monsoon? Don''t guess — get a proper diagnosis. We work on RCC homes and flats in Guwahati, not tin sheet roofs.","primaryCta":{"label":"Book free inspection","href":"/contact#inspection-form"},"secondaryCta":{"label":"What''s wrong with my building?","href":"/problems"},"image":"images/hero.jpg"},"homeSections":{"earthquakes":{"eyebrow":"Live map","headline":"Recent tremors near Guwahati."},"capabilities":{"eyebrow":"Solutions","headline":"Technical services after diagnosis."},"work":{"eyebrow":"Projects","headline":"Buildings we''ve rehabilitated."},"process":{"eyebrow":"How we work","headline":"Diagnose first. Fix properly."},"team":{"eyebrow":"About","headline":"Engineering-led, not sales-led."},"clients":{"eyebrow":"Clients","headline":"Trusted across Guwahati & NE."},"backing":{"eyebrow":"Backing","headline":"Assam Startup · MSME registered."},"contact":{"eyebrow":"Contact","headline":"Ready for a free inspection?","body":"Tell us what''s worrying you — leak, crack, or damp wall. We''ll inspect and advise honestly."},"problemGrid":true,"doctorPositioning":true,"inspectionCta":{"headline":"Not sure what''s causing the problem?","body":"Upload photos or book a site visit. We''ll inspect, diagnose, and give you a clear repair plan — before you commit to any work.","primaryLabel":"Book inspection","primaryHref":"/contact#inspection-form","secondaryLabel":"Try self-assessment","secondaryHref":"/assessment","slaNote":"Same-day phone callback on weekdays (before 4 PM). Site visit within 48 hours inside Guwahati city limits."},"googleReviews":{"eyebrow":"Google reviews","headline":"Rated by Guwahati customers"},"guides":{"eyebrow":"Guides","headline":"Guwahati homeowner guides"}},"nav":[{"label":"Home","href":"/"},{"label":"Problems","href":"/problems"},{"label":"Projects","href":"/portfolio"},{"label":"Knowledge","href":"/knowledge"},{"label":"Earthquakes","href":"/earthquakes"}],"navToolsLabel":"Tools","navTools":[{"label":"Analyzer","href":"/analyzer"},{"label":"Assessment","href":"/assessment"}],"navMore":[{"label":"Education","href":"/education"},{"label":"About","href":"/about"},{"label":"Contact","href":"/contact"}],"cta":{"label":"Check your home","href":"/assessment"},"social":{"facebook":"https://www.facebook.com/91skylineworks","instagram":"https://www.instagram.com/91skylineworks","linkedin":"https://www.linkedin.com/company/91skylineworks"},"stats":[{"value":15,"suffix":"+ yrs","label":"Serving Guwahati homes"},{"value":120,"suffix":"+","label":"Homes & buildings strengthened"},{"value":1.8,"suffix":"M sq ft","label":"Area made safer"},{"value":5,"suffix":"/5","label":"Client rating"}],"process":[{"step":1,"title":"We visit your home","description":"Our engineer walks through your flat or house — checking columns, concrete terrace, bathroom, basement, and any cracks you''ve noticed. No charge for the first consultation in Guwahati."},{"step":2,"title":"We test what''s hidden","description":"If needed, we run a building strength test — like an X-ray for your concrete, without breaking it open (NDT). You''ll know if the structure is actually strong or just looks fine from outside."},{"step":3,"title":"We strengthen & repair","description":"We fix the root cause — wrapping weak columns, stopping water through concrete, filling hollow pockets — using methods suited to your building and budget."},{"step":4,"title":"You get a clear report","description":"Plain-language summary of what we found, what we did, and what to watch for. No engineering jargon without explanation."}],"about":{"eyebrow":"Who we are","headline":"Guwahati engineers who speak your language.","body":["91SkylineWorks helps homeowners in Guwahati and Assam fix the problems that keep families awake at night — cracks after tremors, monsoon roof leaks, damp walls, and the nagging question: is my building actually safe?","We''re not here to scare you. We''re here because most people don''t know the difference between a harmless paint crack and a column crack that could fail in the next earthquake. That awareness gap costs lives and lakhs in repairs."],"points":["Retrofitting for earthquake safety in Zone V","Waterproofing before monsoon damage spreads","Building strength tests before you buy or renovate","Assam Startup (2022) · NEEDP (2023) · NEDFi backed"],"image":"images/about.jpg"},"team":[{"name":"Rahul Jyoti Nath","role":"Your contact for home assessments","credentials":"M.Sc., University of Bonn · B.Tech, NIT Silchar","bio":"Rahul works directly with Guwahati homeowners and private clients. He explains what''s wrong with your building in plain Assamese and English — what must be fixed now, what can wait, and what it will cost. No pressure, no jargon.","image":"/images/rahul-pic.jpeg"}],"clients":[{"name":"Guwahati Municipal Corporation","location":"Guwahati","rating":5},{"name":"Assam Agricultural University","location":"Jorhat","rating":5},{"name":"Gauhati University","location":"Jalukbari","rating":5},{"name":"HPCL","location":"Guwahati","rating":5},{"name":"Subham Builders","location":"Guwahati","rating":5},{"name":"Numaligarh Refinery Ltd.","location":"Golaghat","rating":5},{"name":"Protech Builder Group","location":"Guwahati","rating":5},{"name":"Cotton University","location":"Guwahati","rating":5}],"backing":[{"title":"Assam Startup (2022)","body":"Incubated through Assam Startup — supporting local engineering ventures focused on safer homes in Guwahati and Assam."},{"title":"NEEDP (2023)","body":"Supported by the North East Entrepreneurship Development Programme for field deployment of retrofitting and building testing across the region."},{"title":"NEDFi","body":"Backed by the North Eastern Development Finance Corporation for institutional and residential building safety projects."}],"telemetry":{"station":"GHY-01 (SILPUKHURI)","baseAcceleration":0.039,"alertStatus":"PROFILE 5 EXHAUSTION THREAT INDEX REGISTERED","engineNote":"Continuous unmonitored micro-tremors expand hidden capillary water pathways, permanently degrading structural steel bonds inside columns."},"earthquakes":{"eyebrow":"Live map","headline":"Recent tremors near Guwahati.","homeIntro":"Guwahati is in India''s highest earthquake zone (Zone V). Small tremors happen regularly — and each one tests cracks you may already have in your columns or walls. These events were recorded recently in our region.","subhead":"Live earthquake map for Northeast India. Tap a dot to see magnitude and location. Enable location to centre the map on you.","bridgeNote":"Our Silpukhuri monitor tracks steady micro-tremor activity in Zone V. Below, verified USGS events show what was recorded near Guwahati — each tremor tests cracks you may already have in your home.","disclaimer":"Data: USGS · ~5 min delay · For information only. Official India alerts: NCS/IMD.","locationNote":"Map centred on your location when allowed.","seoTitle":"Earthquakes Near Guwahati Today — Live Map | Assam & Northeast India","seoDescription":"Recent earthquakes near Guwahati, Assam and Northeast India. Live USGS seismic map — enable location to see tremors near you. Seismic Zone V building guidance from 91SkylineWorks.","faq":[{"q":"Where can I see earthquakes near Guwahati today?","a":"91SkylineWorks publishes a live earthquake map for Northeast India using verified USGS data. Open the Earthquakes page to view recent tremors near Guwahati, Assam and surrounding states, or enable location to centre the map on you."},{"q":"Is Guwahati in a high earthquake zone?","a":"Yes. Guwahati is in IS seismic Zone V — India''s highest earthquake hazard category. Small tremors are common and each event can stress existing cracks in columns, beams and walls."},{"q":"How often do earthquakes happen in Northeast India?","a":"The Northeast India region records frequent minor and moderate seismic activity. USGS typically lists multiple events above magnitude 2.5 each week across Assam, Meghalaya, Arunachal Pradesh and neighbouring areas."},{"q":"Should I worry about small tremors near my home?","a":"Small tremors rarely cause new damage in well-built structures, but they can widen existing structural cracks. If you notice cracks at beam-column joints or diagonal wall cracks, book a structural inspection rather than waiting for a larger event."},{"q":"Where does the earthquake data come from?","a":"Event data is sourced from the US Geological Survey (USGS) public feed, with roughly a five-minute delay. For official India alerts, refer to the National Centre for Seismology (NCS) and IMD."}]},"education":{"sections":[{"title":"Frame Structural Mechanics (Columns vs. Infill Walls)","body":"Many property owners mistake brickwork partition cracks for benign settling. Brick walls carry zero structural load and exist purely for privacy and decoration. The entire weight profile of the building is carried by the columns, beams, and slabs. One single unchecked crack in a load-bearing column or beam intersection completely interrupts the structural load distribution path. Under sudden lateral earthquake loads, these compromised joints suffer sudden brittle failure, initiating total progressive collapse."},{"title":"The Internal Pathology of Water Seepage","stages":[{"label":"Stage 01 [Capillary Absorption]","text":"Ingress from roofs or damp bathroom areas penetrates deep into concrete pores."},{"label":"Stage 02 [Chemical Leaching]","text":"Migrating moisture dissolves and leaches out calcium hydroxide, creating invisible internal void structures inside structural concrete frames."},{"label":"Stage 03 [Rebar Expansion Catalyst]","text":"Moisture contacts internal steel reinforcement rebar, initiating oxidation. Rusting steel expands up to 600% of its original physical volume."},{"label":"Stage 04 [Structural Spalling]","text":"This extreme internal pressure causes the concrete to split and flake off from the inside out, dropping structural integrity to zero."}]},{"title":"Global Compliance Indices (NDT & Retrofitting Lifecycles)","body":"International building code standards (ACI 318) and Indian concrete codes (IS 456) explicitly mandate that all commercial, public, and high-occupancy residential structures undergo systematic Non-Destructive Testing (NDT) audits (utilizing Ultrasonic Pulse Velocity mapping and Rebound Hammer arrays) every 3 to 5 years to uncover deep-seated hidden vulnerabilities."}]},"advisory":{"title":"New Home Buyer''s Technical Advisory","points":[{"title":"Pre-Tile Membrane Integration","body":"Execute high-performance elastomeric polyurethane waterproofing directly onto raw bathroom concrete matrices before laying tiles. Remediating sub-surface capillary leaks later by breaking finished tile arrays costs up to 500% more than implementing preventive barriers on day zero."},{"title":"Acquisition NDT Testing","body":"Never buy or take ownership of an asset based on a visually fresh coat of cosmetic paint. Insist on a formal NDT diagnostic assessment to evaluate the hidden compressive core strength of the building skeleton before finalizing real estate transactions."}]},"projects":[{"slug":"beltola-residential-tower","title":"Beltola Residential Tower","category":"Residential","location":"Beltola, Guwahati","year":2024,"scope":"Full terrace waterproofing with slope correction and parapet upturn for 48-unit society","featured":true,"image":"images/projects/beltola-residential-tower/hero.webp","outcome":"Zero ceiling leak complaints post-monsoon 2024","services":["waterproofing","expansion-joints"],"caseStudy":true,"challenge":"48-unit society on Beltola — three monsoons of ceiling stains on top-floor flats. Previous contractor had applied single-coat acrylic without slope or parapet detail.","solution":"Removed failed layers, corrected terrace slope to drains, double-coat PU membrane, parapet upturn, penetration seals, and 24-hour flood test before handover.","beforeSummary":"Standing water on terrace; damp patches on 4th–5th floor ceilings after every rain.","afterSummary":"Zero leak complaints through monsoon 2024. Society received written warranty and drain maintenance checklist.","body":"The RWA board wanted a fixed per-sq-ft quote over WhatsApp. We insisted on flood test first — water was entering at pipe collars and a reversed slope pocket near the lift machine room.\\n\\nPhased work over 12 days: drain clearance, screed correction, membrane, protection course. Expansion joints between blocks resealed in the same contract.\\n\\nThis is the job type Rehabari applicators underbid — and the reason we publish photos, not just logos."},{"slug":"chandmari-apartment-complex","title":"Chandmari Apartment Complex","category":"Residential","location":"Chandmari, Guwahati","year":2023,"scope":"Bathroom seepage repair, PU injection at slab joints, expansion joint reseal","featured":true,"image":"images/projects/chandmari-apartment-complex/hero.webp","outcome":"Resolved inter-floor leakage affecting 12 flats","services":["pu-injection","waterproofing"],"caseStudy":true,"challenge":"Active water ingress through slab joints — 12 flats with bathroom and bedroom stains. Prior PU injection failed because cracks were still moving.","solution":"Crack mapping, low-pressure PU injection at active leaks, expansion joint reseal, bathroom membrane at two worst units.","beforeSummary":"Inter-floor seepage; residents using buckets during heavy rain.","afterSummary":"Dry ceilings through peak monsoon. PU injection points documented for future monitoring.","body":"SS Water Proofing-style quick injection without mapping had failed twice. We mapped movement first, injected in stages, flood-tested bathrooms before tiles.\\n\\nHomeowners got a one-page diagnosis — not a verbal ''all fixed''."},{"slug":"hpcl-regional-facility","title":"HPCL Regional Facility","category":"Industrial","location":"Guwahati","year":2024,"scope":"Basement waterproofing, hydrostatic barrier, column spalling repair","featured":false,"image":"images/projects/hpcl-regional-facility/hero.webp","outcome":"Dry basement storage through peak monsoon","services":["waterproofing","structural-repairs"]},{"slug":"dispur-government-office","title":"Dispur Government Office","category":"Institutional","location":"Dispur, Guwahati","year":2023,"scope":"Column crack mapping, epoxy injection, CFRP wrap on critical members","featured":true,"image":"images/projects/dispur-government-office/hero.webp","outcome":"Structural audit clearance for occupancy continuation","services":["epoxy-injection","carbon-fibre","ndt"],"caseStudy":true,"challenge":"Diagonal cracks on multiple columns after tremors — occupancy audit required NDT proof and repair design before continued use.","solution":"Crack mapping, UPV and rebound hammer screening, epoxy injection on dry cracks, CFRP wrap on critical columns, handover NDT report.","beforeSummary":"Visible column cracks; audit flagged structural concern for staff occupancy.","afterSummary":"Structural clearance for continued occupancy. Strengthened members documented with before/after photos and test results.","body":"Not every crack needed CFRP — we classified cosmetic plaster separately from through-column cracks. That honesty saved the department budget and built trust.\\n\\nPDCE-style testing plus execution in one contract — no consultant-to-contractor handoff delay."},{"slug":"industrial-warehouse-paltan-bazar","title":"Paltan Bazar Warehouse","category":"Industrial","location":"Paltan Bazar, Guwahati","year":2022,"scope":"Foundation grouting for settlement under warehouse slab","featured":false,"image":"images/projects/industrial-warehouse-paltan-bazar/hero.webp","outcome":"Settlement stabilised — slab movement arrested","services":["pu-injection"]},{"slug":"gs-road-commercial-block","title":"GS Road Commercial Block","category":"Commercial","location":"GS Road, Guwahati","year":2024,"scope":"Podium waterproofing and parking expansion joint treatment","featured":true,"image":"images/projects/gs-road-commercial-block/hero.webp","outcome":"Dry parking level through monsoon","services":["waterproofing","expansion-joints"],"caseStudy":true,"challenge":"Stilt parking flooded every monsoon — water through podium expansion joints and ramp entrance. Shop tenants threatened rent withholding.","solution":"Podium flood test, joint sealant replacement, waterproof coating on podium slab, ramp water-stop detail.","beforeSummary":"Parking unusable during storms; efflorescence on columns at parking level.","afterSummary":"Dry parking through monsoon. Joint treatment scheduled on 3-year society maintenance calendar.","body":"Society managers often treat parking leaks as ''not structural''. We tied joint failure to column exposure — rust risk if ignored.\\n\\nPhased parking closure on weekends only — tenants could still operate weekdays."},{"slug":"six-mile-school-campus","title":"Six Mile School Campus","category":"Institutional","location":"Six Mile, Guwahati","year":2023,"scope":"Seismic screening and column jacketing on 1998 block","featured":false,"image":"images/projects/six-mile-school-campus/hero.webp","outcome":"Retrofit completed during summer break","services":["seismic-jacketing","ndt"]},{"slug":"zoo-road-hotel-terrace","title":"Zoo Road Hotel Terrace","category":"Hospitality","location":"Zoo Road, Guwahati","year":2024,"scope":"Terrace PU membrane, heat reflective coating, drain redesign","featured":true,"image":"images/projects/zoo-road-hotel-terrace/hero.webp","outcome":"Guest room leak complaints eliminated","services":["waterproofing","heatproofing"],"caseStudy":true,"challenge":"Guest rooms on the top two floors reported leaks every monsoon — online reviews mentioned damp smell. Hotel could not strip all rooms during peak season.","solution":"Phased terrace PU membrane by wing, heat-reflective top coat, drain redesign, and night-only work on occupied floors.","beforeSummary":"Terrace ponding; guest complaints and booking impact each May–September.","afterSummary":"Leak tickets dropped to zero post-monsoon. Management uses our photo log for annual maintenance planning.","body":"Hotels cannot close during tourist season. We worked in zones — flood test each section before membrane, heat-reflective coat to cut AC load on top floor.\\n\\nCompetitors offered acrylic re-coat in two days. We mapped leak paths first; active cracks got PU injection before membrane."},{"slug":"noonmati-housing-retrofit","title":"Noonmati Housing Retrofit","category":"Residential","location":"Noonmati, Guwahati","year":2022,"scope":"CFRP column wrap and micro concreting on honeycombed columns","featured":true,"image":"images/projects/noonmati-housing-retrofit/hero.webp","outcome":"NDT strength targets met post-repair","services":["carbon-fibre","micro-concreting"],"caseStudy":true,"challenge":"Honeycombed columns and low UPV readings in a 1990s walk-up — owners feared earthquake risk but did not want bulky steel jackets.","solution":"NDT screening, micro concreting for voids, CFRP column wrap on deficient members, re-test after cure.","beforeSummary":"Hollow-sounding columns; visible honeycomb; NDT below target on two ground-floor members.","afterSummary":"Post-repair UPV met agreed targets. Owners received diagnosis pack and 10-year workmanship warranty on wrap.","body":"Retrofit without eviction — CFRP kept column size nearly unchanged. Alternative steel jacket quotes were rejected by owners for space and appearance.\\n\\nWe beat Avicon on speed for a small residential job they would spec but rarely photograph."},{"slug":"bhangagarh-hospital-basement","title":"Bhangagarh Hospital Basement","category":"Institutional","location":"Bhangagarh, Guwahati","year":2023,"scope":"Basement tanking, PU injection, humidity control coordination","featured":false,"image":"images/projects/bhangagarh-hospital-basement/hero.webp","outcome":"Medical storage area humidity within spec","services":["waterproofing","pu-injection"]}],"services":[{"code":"01","slug":"retrofitting","title":"Retrofitting","description":"Crack in a column? Don''t paint over it. We strengthen the columns and beams you already have so the next tremor doesn''t bring the floor down (retrofitting).","category":"retrofitting"},{"code":"02","slug":"waterproofing","title":"Waterproofing","description":"Monsoon leaks through RCC terraces, bathrooms, and basements — not tin sheet roofs. We stop water before it rusts the steel inside your concrete.","category":"waterproofing"},{"code":"03","slug":"ndt","title":"Building Strength Test","description":"Buying a resale flat in Beltola or Chandmari? Get an X-ray for your concrete first (NDT) — without breaking anything. Hidden weakness shows up before you sign.","category":"ndt"},{"code":"04","slug":"heatproofing","title":"Heatproofing","description":"Top-floor flat unbearable in April–June? Weather Cool coating drops roof surface temperature by up to 14°C — less AC, lower bills.","category":"heatproofing"},{"code":"05","slug":"expansion-joints","title":"Expansion Joint Treatment","description":"Gaps between building blocks let monsoon water in. We seal joints properly so water and cracks don''t spread through your apartment complex.","category":"waterproofing"},{"code":"06","slug":"rainwater-harvesting","title":"Rainwater Harvesting","description":"Guwahati gets heavy rain — most of it wasted. Capture rooftop water for flushing and gardening, or recharge your borewell before it runs dry.","category":"rainwater-harvesting"},{"code":"07","slug":"pu-injection","title":"PU Injection Grouting","description":"Stop active water leaks through cracks — polyurethane injection expands with water to seal basements, terraces, and joints.","category":"waterproofing"},{"code":"08","slug":"epoxy-injection","title":"Epoxy Injection","description":"Restore structural strength in dry cracks — epoxy bonds concrete in columns and beams for load-bearing repair.","category":"retrofitting"},{"code":"09","slug":"carbon-fibre","title":"Carbon Fibre Strengthening","description":"CFRP wrapping adds earthquake strength without bulky columns — ideal for Guwahati apartment retrofits.","category":"retrofitting"},{"code":"11","slug":"structural-repairs","title":"Structural Repairs","description":"Spalling repair, rebarring, micro concreting, and jacketing — fix damaged concrete before it fails.","category":"retrofitting"},{"code":"12","slug":"micro-concreting","title":"Micro Concreting","description":"Fill honeycomb and voids inside columns and slabs without breaking open the structure.","category":"retrofitting"},{"code":"13","slug":"seismic-jacketing","title":"Seismic Jacketing","description":"Column and beam jacketing per IS codes — confinement steel and high-strength grout for Zone V buildings.","category":"retrofitting"},{"code":"14","slug":"concrete-cancer-treatment","title":"Concrete Cancer Treatment","description":"Treat corroded steel, delaminated concrete, and chloride damage before spalling spreads.","category":"retrofitting"}],"servicePages":[{"slug":"retrofitting","title":"Retrofitting","headline":"Make the home you already have stronger","intro":"Guwahati sits in India''s highest earthquake zone (Zone V). Retrofitting means strengthening the columns, beams, and foundations you already have — so the next tremor doesn''t turn a small crack into a collapsed floor.","awareness":{"headline":"That crack in your column is not ''settling''","body":"Most Guwahati homeowners ignore cracks because the builder said it''s settling, or because paint hides it. A crack in a partition wall between rooms is usually harmless. A crack running through a column, a beam, or where the wall meets the ceiling is not. In a tremor, that weak point can fail — and everything above it comes down. Don''t wait until you feel the next one to find out."},"offerings":[{"name":"Carbon fibre wrapping (CFRP)","description":"Thin, high-strength carbon fibre sheets wrapped around a weak column or beam — like a cast for the building''s skeleton. Adds strength without making columns bulky. Useful in occupied flats.","whenUsed":"Cracks or lost strength in columns/beams, but the building is still saveable — common in 15–30 year RCC flats in Guwahati.","whyItMatters":"A weak column can buckle in a moderate earthquake. Floors above can pancake. Repair after collapse costs far more than strengthening now — if the building is even salvageable."},{"name":"Filling hollow concrete (micro concreting)","description":"High-strength grout injected into empty or honeycombed pockets inside concrete — voids left by poor pouring or age.","whenUsed":"A building strength test shows empty pockets, or tapping a column sounds hollow.","whyItMatters":"Hollow concrete leaves steel unprotected. Water reaches the steel, rust expands, and concrete bursts from inside — often with no warning on the surface."},{"name":"Repair mortar","description":"Structural mortar seals cracks in concrete and restores the surface — stopping monsoon water from reaching the steel inside.","whenUsed":"Visible cracks in columns or beams, concrete flaking off, or damp patches on structural members.","whyItMatters":"Rusted steel expands up to six times. What looks like a hairline crack today can become a crumbling column after one wet monsoon."},{"name":"Grouting","description":"Cement or epoxy grout fills gaps in masonry, between columns and brickwork, and in uneven foundations — so load spreads evenly again.","whenUsed":"Uneven floors, doors that don''t close, or gaps after settling or tremors.","whyItMatters":"Uneven load puts extra stress on fewer columns. One column takes the weight of three — and fails first in an earthquake."},{"name":"Replacing rusted steel (rebarring)","description":"Corroded steel bars inside concrete are exposed, cleaned, and replaced or supplemented — then sealed again.","whenUsed":"Concrete has fallen off and rusted steel is visible, or tests show the bars have lost strength.","whyItMatters":"Rusted steel can lose half its strength silently. The building looks fine until a tremor."},{"name":"Foundation strengthening","description":"Stabilising foundations that have settled, tilted, or sit on soft Guwahati soil.","whenUsed":"Older homes in low-lying areas (Bharalumukh, Pandu, parts of Noonmati) with tilting, sloping floors, or cracks at plinth level.","whyItMatters":"Foundation failure affects the whole building. In a strong quake, an untreated foundation can shift — tearing pipes and splitting the structure."}],"sections":[{"title":"When to call us","bullets":["A crack runs through a column or beam — not just plaster between rooms","A crack comes back after you paint it","You felt a tremor and new cracks appeared","The building is 15+ years of RCC and has never been checked","You are adding a floor, a water tank, or extra load"]},{"title":"Column crack vs paint crack","body":"A fine crack in plaster between two rooms is usually cosmetic — that brick wall carries no load. A crack that follows a column, runs diagonally at a wall-ceiling joint, or widens after each tremor is structural. If you can fit a coin into it, or it reappears after paint, call us."},{"title":"What we don''t do","bullets":["We don''t build new houses or take on general contracting","We don''t ''just plaster it'' and call a column crack fixed — paint hides risk, it doesn''t restore strength","We don''t skip a strength test (NDT) when columns look doubtful — strengthening without diagnosis is guessing"]},{"title":"How we work","bullets":["Site visit and crack mapping","Building strength test (NDT) on suspect columns and beams","Repair design in plain language — what must be done now, what can wait","Carbon fibre wrap, jacketing, or injection as specified","Final test and a handover report you can actually read"]},{"title":"What happens in the next tremor","body":"Untreated cracked column: the tremor concentrates stress at the crack, the column shears, upper floors lose support. Strengthened home: the same tremor is absorbed by treated columns — cracks may not grow, floors stay supported."},{"title":"Concrete does not stay strong forever","body":"A 25-year column in Guwahati monsoon can test well below what it was designed for if nobody ever maintained it. Water and rust eat the steel inside. A building strength test (NDT) shows that before a tremor does."}],"ctaMessage":"Seen a crack? Don''t wait for the next tremor. Free consultation — we''ll tell you honestly if it''s serious.","seoTitle":"Building retrofitting in Guwahati","seoHeadline":"Building retrofitting in Guwahati","warranty":{"term":"10 years on specified structural repair","covers":["CFRP wrap, jacketing, epoxy injection, and grouting executed under our design","Workmanship defect in materials we supplied and installed"],"voids":["New loading, illegal construction, or unapproved structural changes after handover","Corrosion progression where client declined recommended member treatment","Cosmetic plaster cracks unrelated to treated structural members"]}},{"slug":"waterproofing","title":"Waterproofing","headline":"Stop monsoon water before it rusts your steel","intro":"We waterproof concrete — RCC terrace slabs, bathrooms, basements, and podiums. Not tin or GI sheet roofs. A small leak on a concrete terrace today becomes a rusted column tomorrow. Waterproofing isn''t paint. It''s how you stop water eating the home from inside.","awareness":{"headline":"That yellow ceiling stain isn''t ''just humidity''","body":"Water travels down through concrete, reaches the steel inside the slab, and starts rust. By the time you see a stain on the bedroom ceiling, damage inside may already be serious. Painting over it makes it invisible — not fixed. This is for concrete terraces and bathrooms, not tin sheet roofs."},"offerings":[{"name":"RCC terrace / concrete slab (not tin sheet)","description":"Two layers of waterproof coating on your concrete terrace — the first line of defence against Guwahati monsoon. This is a flat RCC slab, the kind on apartment buildings and pucca houses — not a tin or GI sheet roof.","whenUsed":"Water pools on the terrace after rain, or the top-floor ceiling has damp patches. Before monsoon if the terrace is already cracked.","whyItMatters":"Standing water finds every crack. One season of unchecked leakage can cut a slab''s remaining life in half."},{"name":"Screed slope correction","description":"We rebuild the terrace slope so water flows to drains instead of sitting in puddles.","whenUsed":"Water pools in corners after rain — common on older Guwahati buildings with flat or reversed slopes.","whyItMatters":"Pooled water finds the weakest point. Every monsoon that spot gets worse until water breaks through."},{"name":"Bathroom waterproofing (before tiles)","description":"Waterproof layer on the raw bathroom floor and walls before tiling — the correct sequence.","whenUsed":"During renovation, before tiles go on. Also when redoing a bathroom that leaks to the flat below.","whyItMatters":"Fixing a leaking tiled bathroom means breaking all the tiles — many times the cost of doing it right the first time."},{"name":"Basement & plinth","description":"Injection (PU) and coating for ground floors and basements — especially where the road has risen above your plinth.","whenUsed":"Ground-floor walls damp year-round, white salt on walls, or water entering in heavy rain.","whyItMatters":"Guwahati''s water table is shallow. Water pushes through walls. Paint fails within months."},{"name":"Flexible coating (PU)","description":"A flexible, durable coat that handles foot traffic on terraces and movement in walls (polyurethane).","whenUsed":"Concrete terraces, balconies, and surfaces that expand and contract with heat.","whyItMatters":"Rigid coatings crack in Guwahati heat. Flexible PU stays sealed."},{"name":"Exterior wall coating","description":"UV-resistant coats that block water on sun-facing walls — not a substitute for a proper terrace membrane.","whenUsed":"Sun-facing walls with fine cracks, or light-traffic terrace surfaces after the slab is prepared.","whyItMatters":"Wall cracks let monsoon water in. One wet season can rust the steel ties inside."}],"sections":[{"title":"When to call us","bullets":["Yellow-brown stains on ceiling or walls after rain","Bathroom leak into the flat below","Before monsoon — if the terrace already ponds or is cracked","Before tiling a bathroom (the membrane goes on the raw floor)","White powder on ground-floor walls, or a musty smell that returns every monsoon"]},{"title":"What we don''t do","bullets":["Tin, GI, or CGI sheet roofs — we do not coat metal sheets. That is a different trade.","Asbestos sheet roofs","Interior painting sold as ''waterproofing'' — paint hides a stain, it does not stop water in the slab","Plumbing-only jobs (leaking tap, burst pipe, WC trap) with no seepage through concrete. Call a plumber first.","New-build contracting — we diagnose and repair existing concrete homes and flats"]},{"title":"The Guwahati monsoon trap","body":"From May to September, rain is almost daily. Flat concrete terraces and old drains can''t cope. If the upstairs terrace isn''t waterproofed, your ceiling pays. If your own terrace has cracks, your columns absorb the water."},{"title":"Diagnosis before coating","body":"We flood-test terraces, map moisture on ceilings, and check parapet and drain details before choosing a system. Coating over active cracks or ponding water fails within one season."},{"title":"Systems we specify (on concrete)","bullets":["Flexible liquid membrane (PU) for terraces people walk on","Bitumen layers with a protection screed where needed","Basement systems that work from the inside when you can''t dig outside","Bathroom membrane before tiles","Parapet upturn and pipe collars — the details cheap jobs skip"]}],"ctaMessage":"Monsoon is coming. If the leak is on concrete — terrace, bathroom, basement — call us. Tin roofs are not our work.","seoTitle":"Waterproofing in Guwahati","seoHeadline":"Waterproofing in Guwahati","warranty":{"term":"5 years","covers":["Membrane failure at treated terrace, bathroom, or basement areas we completed","Leak recurrence at detailed penetrations, parapet upturns, and drains included in scope"],"voids":["New cracks from structural movement or earthquake damage after handover","Third-party damage, tile breaking, or drain blockage by others","Areas outside agreed scope or where client declined recommended prep work"]}},{"slug":"ndt","title":"Building Strength Test","headline":"Know if your building is actually strong","intro":"A fresh paint job hides a lot. A building strength test is an X-ray for your concrete without breaking anything open (NDT — non-destructive testing). It tells you what''s inside columns and slabs before you buy, retrofit, or ignore a crack.","awareness":{"headline":"Don''t buy a Guwahati flat on looks alone","body":"Families buy resale flats in Beltola, Six Mile, and Zoo Road based on location and paint. They don''t know the bedroom column is hollow inside. They find out after the first monsoon leak — or after a tremor. A half-day test costs a fraction of the down payment."},"offerings":[{"name":"Ultrasound of concrete (UPV)","description":"Sound waves through concrete — like an ultrasound. Weak, hollow, or cracked zones show up on the reading (ultrasonic pulse velocity).","whenUsed":"You need to know what''s inside columns, slabs, and load-bearing walls — before buying or before strengthening.","whyItMatters":"Hollow concrete can look perfect from outside. This test finds the voids before they become collapse points."},{"name":"Surface hardness test (rebound hammer)","description":"A spring-loaded device measures how hard the concrete surface is — a quick clue to compressive strength.","whenUsed":"Screening many columns and slabs on a pre-purchase visit.","whyItMatters":"Soft concrete means poor mix or age. It will not carry earthquake load as designed."},{"name":"Crack mapping & risk report","description":"We measure, photograph, and classify every crack — structural vs cosmetic — in a report you can read.","whenUsed":"After tremors, when buying, or when several cracks appear across the flat.","whyItMatters":"Not all cracks are equal. Without mapping you either panic or ignore something dangerous."},{"name":"Pre-purchase building report","description":"Full strength assessment before you pay a deposit — clear pass/fail on each structural element.","whenUsed":"Before signing any resale flat or independent house in Guwahati.","whyItMatters":"Banks check paperwork, not concrete. You''re the one living there when something fails."}],"sections":[{"title":"When to get a strength test","bullets":["Before you buy a resale flat or old house","Before you spend on strengthening (retrofitting) — so the repair matches the actual weakness","After a tremor, or when new cracks appear","Buildings 10+ years old, especially pre-2010 RCC","Every 3–5 years on older occupied buildings — not a one-time stamp"]},{"title":"What this is not","bullets":["Not a substitute for repair — a test finds the problem; strengthening or waterproofing fixes it","Not a paperwork stamp for a builder or a new construction project","Not something you do instead of calling us about a leaking tin roof — we don''t coat sheet roofs"]},{"title":"What you''ll receive","body":"A clear report in plain language — not a 50-page engineering document. Which columns passed, which need attention, and what it will cost to fix. You decide: buy, negotiate, walk away, or repair."},{"title":"Concrete weakens with age","body":"Water, rust, and thinning cover reduce strength over decades — often with no warning until concrete flakes or a tremor widens a crack. The hammer and ultrasound tests show what paint hides. A building that ''looks fine'' at 20 years may have columns below design strength."},{"title":"Other states already require audits","body":"Maharashtra requires structural audits on certain old buildings. Delhi has pushed periodic safety checks. Assam has not mandated the same yet — owners who wait for the law often pay emergency prices after failure."}],"ctaMessage":"Buying, or worried after a tremor? Book a building strength test — we''ll explain the readings in plain language."},{"slug":"heatproofing","title":"Heatproofing","headline":"Survive Guwahati summer without ₹10,000 AC bills","intro":"If you live on the top floor in Guwahati, you already know — April to June is unbearable. Heatproofing reflects sun off your roof so your flat stays cooler and your AC works less.","awareness":{"headline":"Your roof is a frying pan — and you''re living under it","body":"Unprotected concrete roofs in Guwahati reach 50–55°C in summer. That heat radiates into your ceiling all night. You''re paying to cool a flat that reheats every afternoon. Heatproofing isn''t luxury — it''s the cheapest way to cut your electricity bill."},"offerings":[{"name":"Weather Cool thermal coating","description":"Advanced reflective coating that bounces sunlight off your terrace — reducing surface temperature by up to 14°C.","whenUsed":"Top-floor flats, exposed terraces, metal roofs, and sun-facing walls.","whyItMatters":"Every degree cooler on the roof = lower AC runtime. Most families recover the cost in one summer season."},{"name":"Multi-layer heat insulation","description":"Combined primer, reflective coat, and protective top layer for maximum heat rejection and durability.","whenUsed":"Large terraces, commercial spaces, and buildings where single-coat hasn''t been enough.","whyItMatters":"Single cheap coatings fail in one monsoon. Multi-layer systems last 5–7 years."}],"sections":[{"title":"Best for Guwahati homeowners","bullets":["Top-floor 2BHK and 3BHK flats in apartment complexes","Independent houses with direct sun on RCC roof","Home offices that overheat by noon","Rental properties — tenants pay AC bills and complain"]},{"title":"Bonus: your roof lasts longer","body":"Heat causes concrete to expand and contract daily — creating micro-cracks that let monsoon water in. Heatproofing reduces thermal stress, so your waterproofing lasts longer too."}],"ctaMessage":"Tired of sweating through summer? One coating before April changes everything."},{"slug":"expansion-joints","title":"Expansion Joint Treatment","headline":"Stop water entering through building gaps","intro":"Those gaps between building blocks in your apartment complex aren''t mistakes — they''re expansion joints. But when sealant fails, monsoon water pours through — into parking, stairwells, and lower floors.","awareness":{"headline":"The gap in your parking lot ceiling is letting water reach your car — and your columns","body":"Expansion joints are designed to let buildings move safely with heat and settling. But in Guwahati''s climate, sealants harden and crack within 3–5 years. Once water enters through a joint, it travels along steel reinforcement — rusting columns from inside while you see nothing on the surface."},"offerings":[{"name":"Joint sealant replacement","description":"Old cracked sealant is removed and replaced with flexible, waterproof material that moves with the building.","whenUsed":"When you see gaps, missing sealant, or water dripping through joints in parking, terrace edges, or stairwells.","whyItMatters":"Water through joints reaches structural steel. Parking slab failure starts at untreated joints."},{"name":"Waterproof joint coating","description":"Additional waterproof layer over treated joints for high-exposure areas like terrace edges and podium levels.","whenUsed":"Joints exposed to direct rain and UV — terrace perimeters, balcony edges, external wall junctions.","whyItMatters":"Sealant alone isn''t enough on exposed joints. Coating adds a second barrier."}],"sections":[{"title":"Common in Guwahati apartment complexes","body":"Multi-block societies in Beltola, Christian Basti, and GS Road areas often have expansion joints between towers, in basement parking, and at terrace junctions. Housing society managers often ignore them until a major leak forces emergency repair — at 3× the preventive cost."},{"title":"For housing societies","bullets":["Schedule joint inspection every 3 years","Treat joints before monsoon, not after leaks appear","Document treatment for maintenance records and resale value"]}],"ctaMessage":"Managing a housing society? Joint treatment now prevents emergency repairs later."},{"slug":"rainwater-harvesting","title":"Rainwater Harvesting","headline":"Guwahati gets enough rain — capture it","intro":"Guwahati receives over 1,700 mm of rain yearly. Most runs off into drains and floods low-lying streets. A simple harvesting system saves money and recharges the groundwater your borewell depends on.","awareness":{"headline":"Your borewell is going dry — and the rain on your roof is wasted","body":"Groundwater across Guwahati is dropping every year. Many homes in Panjabari, Kahilipara, and Narengi run borewells dry by March. Meanwhile, monsoon rain floods the terrace and goes straight to the drain. Harvesting connects the two problems into one solution."},"offerings":[{"name":"Rooftop collection system","description":"Gutters and pipes channel clean rainwater from your terrace into storage tanks.","whenUsed":"Homes with large terrace area — ideal for flushing, gardening, and car washing.","whyItMatters":"A 100 sq m roof in Guwahati can collect 1.7 lakh litres annually. That''s free water you''re currently throwing away."},{"name":"Borewell recharge pit","description":"Filtered rainwater is directed underground to recharge your borewell aquifer.","whenUsed":"When your borewell water level drops seasonally or the pump runs longer each year.","whyItMatters":"Recharge pits can raise water table by metres over 2–3 monsoons — extending borewell life by decades."},{"name":"Storage tank installation","description":"Overground or underground tanks store harvested water for daily non-drinking use.","whenUsed":"When you want immediate usable water, not just groundwater recharge.","whyItMatters":"Stored rainwater cuts municipal water bills and provides backup during supply cuts."}],"sections":[{"title":"Why Guwahati needs this now","body":"Urban flooding in Guwahati worsens each year because hard surfaces send rain to drains too fast. Harvesting on your property reduces runoff, lowers your water bill, and helps the neighbourhood aquifer. Many municipalities now encourage or require harvesting for new construction."},{"title":"Simple payback","bullets":["Lower Jio/NRL water tanker costs in dry months","Reduced flooding in your compound","Higher property value with green certification","Works alongside terrace waterproofing — we coordinate both"]}],"ctaMessage":"Before next monsoon — set up harvesting and never watch rain go to waste again."},{"slug":"pu-injection","title":"PU Injection Grouting","headline":"Stop active leaks at the source","intro":"Polyurethane injection is our go-to when water is actively pushing through cracks — in basements, terrace slabs, and expansion joints across Guwahati.","awareness":{"headline":"PU injection reacts with water — rigid fillers do not","body":"When water is moving through a crack under pressure, cement or paint fails immediately. PU grout travels into the crack, reacts with moisture, and expands to form a flexible watertight seal."},"offerings":[{"name":"Crack injection","description":"Packers placed along crack path deliver PU under controlled pressure.","whenUsed":"Active basement and terrace leaks","whyItMatters":"Stopping water prevents steel corrosion that weakens the whole member."},{"name":"Joint injection","description":"Expansion and construction joints injected with hydrophilic PU.","whenUsed":"Parking podium and block junction leaks","whyItMatters":"Joint leaks saturate columns from inside — invisible until spalling."}],"sections":[{"title":"When PU injection is the right call","body":"Active water through a crack or joint — basement during monsoon, terrace slab, expansion joint, pipe penetration. PU reacts with water and expands to seal. Dry structural cracks need epoxy, not PU alone."},{"title":"Monsoon urgency","body":"Active leaks accelerate steel corrosion inside slabs and columns. Every week water reaches reinforcement, rust expands, and repair scope grows. Emergency PU injection can run during rain; full waterproofing follows once the leak path is sealed."},{"title":"PU injection process","bullets":["Locate leak path — not just visible drip point","Drill packers along crack or joint at set spacing","Inject hydrophilic or hydrophobic PU under pressure","Verify seal with water test","Finish surface and recommend permanent waterproofing where needed"]},{"title":"Common Guwahati applications","bullets":["Basement retaining wall seepage","Terrace slab hairline leaks before membrane","Expansion joint active leakage","Construction joint between blocks","Pipe sleeve and penetration leaks"]}],"ctaMessage":"Leaking crack? Book inspection — we test whether PU, epoxy, or both are needed."},{"slug":"epoxy-injection","title":"Epoxy Injection","headline":"Restore strength in structural cracks","intro":"Epoxy injection structurally welds cracked concrete back together — used in columns, beams, and foundations when water is controlled.","awareness":{"headline":"Epoxy is structural glue — not a leak plug","body":"Low-viscosity epoxy penetrates hairline cracks and restores monolithic behaviour. It is not for gushing leaks — those need PU first, then epoxy once dry."},"offerings":[{"name":"Low-viscosity epoxy injection","description":"Epoxy injected under pressure along crack plane.","whenUsed":"Dry structural cracks in columns and beams","whyItMatters":"Unrepaired structural cracks concentrate earthquake force at one point."},{"name":"Crack stitching","description":"Steel staples or CFRP strips across crack to prevent reopening.","whenUsed":"Masonry and concrete cracks that move seasonally","whyItMatters":"Injection alone may reopen if underlying movement continues."}],"sections":[{"title":"Epoxy injection process","bullets":["Crack mapping and marking","Surface sealing and port installation","Low-viscosity epoxy injection under pressure","Port removal and finish"]}],"ctaMessage":"Column crack? Get structural assessment before monsoon widens it."},{"slug":"carbon-fibre","title":"Carbon Fibre Strengthening","headline":"Add earthquake strength without bulk","intro":"CFRP wrapping strengthens weakened columns and beams with minimal thickness — preferred in occupied Guwahati flats where space and aesthetics matter.","awareness":{"headline":"CFRP is engineering fabric — not cosmetic wrap","body":"Carbon fibre sheets are epoxy-bonded after surface prep and designed for required capacity increase. Wrong application fails in first tremor."},"offerings":[{"name":"Column CFRP wrapping","description":"Full or partial wrap increases confinement and shear capacity.","whenUsed":"Under-strength or cracked columns in retrofit projects","whyItMatters":"Weak columns are first to fail in progressive collapse."},{"name":"Beam flexural strengthening","description":"CFRP strips on beam soffit increase bending capacity.","whenUsed":"Beams with insufficient steel or load additions","whyItMatters":"Beam failure drops slabs — high casualty risk."}],"sections":[{"title":"CFRP vs steel jacketing","body":"CFRP is thinner and faster in occupied buildings. Steel jacketing suits heavy industrial loads. We specify based on NDT and structural calc."}],"ctaMessage":"Weak column identified in NDT? CFRP may avoid costly demolition."},{"slug":"structural-repairs","title":"Structural Repairs","headline":"Fix spalling before chunks fall","intro":"Comprehensive structural repair — expose corroded steel, treat rust, reinstate cover, and restore load path in Guwahati buildings damaged by age, leaks, or tremors.","awareness":{"headline":"Patching spalled concrete without treating steel fails in one monsoon","body":"Proper repair follows IS 15988 principles: remove loose material, clean steel to bright metal, passivate, and rebuild with structural repair mortar."},"offerings":[{"name":"Spalling repair","description":"Full depth repair to rebar with compatible mortar.","whenUsed":"Balconies, parapets, columns with exposed rust","whyItMatters":"Falling concrete is life safety hazard."},{"name":"Rebarring","description":"Supplement or replace corroded bars.","whenUsed":"Section loss exceeds acceptable limits","whyItMatters":"Corroded bar may have lost 50% capacity silently."}],"sections":[{"title":"Repair vs replace decision","body":"NDT and cover survey determine whether local repair suffices or full member strengthening (CFRP/jacket) is required."}],"ctaMessage":"Spalling on balcony edge? Treat as urgent — book inspection."},{"slug":"micro-concreting","title":"Micro Concreting","headline":"Fill voids inside hollow concrete","intro":"High-strength grout injection fills honeycomb and voids in columns and slabs — common in rushed Guwahati construction from 2000–2015.","awareness":{"headline":"Hollow columns sound fine until they are not","body":"Tap test and UPV reveal voids. Micro concreting packs voids under pressure without demolishing the member."},"offerings":[{"name":"Pressure grouting","description":"Low-shrink grout injected through drilled ports.","whenUsed":"Honeycomb in columns, beam pockets, slab voids","whyItMatters":"Void leaves steel unprotected — corrosion accelerates."}],"sections":[{"title":"Often combined with CFRP","body":"After void fill, CFRP wrap restores confinement if section was weakened."}],"ctaMessage":"Hollow sound on column? NDT first, then micro concreting if confirmed."},{"slug":"seismic-jacketing","title":"Seismic Jacketing","headline":"Zone V retrofit for older RCC frames","intro":"Column and beam jacketing with steel angles, ties, and high-strength grout — brings pre-code Guwahati buildings closer to modern ductile behaviour.","awareness":{"headline":"Pre-2005 buildings often lack ductile detailing","body":"Jacketing adds confinement reinforcement so columns can deform without brittle shear failure during earthquake."},"offerings":[{"name":"RC jacketing","description":"Additional concrete and steel around existing column.","whenUsed":"Severely under-strength columns with space available","whyItMatters":"Brittle column failure causes pancake collapse."},{"name":"Steel jacketing","description":"Steel cage with grout fill for rapid retrofit.","whenUsed":"Occupied buildings needing faster execution","whyItMatters":"Delaying retrofit in Zone V is gambling with lives."}],"sections":[{"title":"Works with NDT and structural audit","body":"Jacketing scope driven by capacity calculation — not one-size template."}],"ctaMessage":"Old building in Guwahati? Seismic screening before next tremor season."},{"slug":"concrete-cancer-treatment","title":"Concrete Cancer Treatment","headline":"Stop corrosion before it spreads","intro":"Concrete cancer is advanced rebar corrosion — treat chloride ingress, carbonation, and ongoing moisture to stop spread across the facade and structure.","awareness":{"headline":"Rust stains today, spalling tomorrow","body":"Half-cell potential and chloride testing map active corrosion zones. Treatment includes removal, passivation, and protective systems."},"offerings":[{"name":"Corrosion mapping","description":"Half-cell and cover survey across affected zones.","whenUsed":"Multiple rust stains or early spalling","whyItMatters":"Corrosion front moves faster than visible damage."},{"name":"Cathodic protection & inhibitors","description":"Where appropriate, slow remaining corrosion in sound cover.","whenUsed":"Large facades and industrial structures","whyItMatters":"Replacing every bar is not always feasible — arrest matters."}],"sections":[{"title":"Must fix leak first","body":"Corrosion treatment without stopping water ingress wastes money — moisture source first, then steel treatment."}],"ctaMessage":"Rust on columns or balcony? Do not paint over — diagnose."}],"contact":{"eyebrow":"Talk to us","headline":"Seen a crack, leak, or damp wall?","body":"Call us about anything worrying you in your home — a crack after a tremor, a ceiling stain after rain, or just the feeling that something isn''t right. We''ll tell you honestly if it needs urgent work or can wait.","phone":"+91 60038 79490","email":"contact@91skylineworks.com","address":"Senapati Road, Sahar Sarania 2nd part, Silpukhuri, Guwahati 781003","hours":"Mon–Sat · 9:00 – 18:00 IST","whatsapp":"+91 60038 79490","whatsappMessage":"Hi, I have a building issue I''d like inspected"},"footer":{"status":"Guwahati field team available — call for home visit","emergencyLabel":"Call for a free consultation","tagline":"Safer homes for Guwahati families.","legal":"© 2026 91SkylineWorks Private Limited. All rights reserved."},"problemCategories":[{"slug":"water-leakage","title":"Water Leakage","icon":"💧"},{"slug":"cracks","title":"Cracks & Structural Damage","icon":"🏗️"},{"slug":"dampness","title":"Dampness & Moisture","icon":"🌧️"},{"slug":"foundation","title":"Foundation Issues","icon":"⬇️"},{"slug":"roof","title":"Roof & Terrace","icon":"🏠"}],"homeProblemGrid":{"headline":"What building problem are you facing?","subhead":"Most homeowners search for symptoms, not solutions. Start here — we''ll help you understand what''s wrong before you spend money fixing it.","ctaLabel":"View all problems"},"doctorPositioning":{"headline":"We diagnose before we prescribe","subhead":"Contractors sell solutions. We find the root cause first — like a doctor for your building.","points":[{"title":"Inspection first","body":"Every project starts with a site visit and diagnosis — not an instant quote over WhatsApp."},{"title":"Test, then repair","body":"We map cracks and moisture, and if needed run a building strength test (NDT), before we recommend stopping water or strengthening columns."},{"title":"Old concrete needs checking","body":"Concrete and the steel inside it weaken over decades — especially in Guwahati monsoon. A strength test every few years catches hidden loss before an emergency."},{"title":"Long-term fix","body":"We fix the cause, not the stain. No paint-over-leak patches that fail next monsoon. We work on concrete homes and flats — not tin sheet roofs."}],"ctaLabel":"Book free inspection","ctaHref":"/contact"},"problems":[{"slug":"basement-water-leakage","category":"water-leakage","title":"Basement Water Leakage","headline":"Why your basement floods every monsoon","intro":"Basement leakage in Guwahati is rarely just a plumbing issue. High water table, poor external waterproofing, and cracked raft slabs let water push in from below and through walls.","symptoms":["Water pooling on basement floor after rain","Damp walls and white salt deposits (efflorescence)","Musty smell and mould on stored items","Pump running constantly during monsoon"],"causes":["Failed external waterproofing membrane","Cracks in raft foundation or retaining walls","Rising groundwater in low-lying areas like Ulubari, Bhangagarh","No proper drainage or sump around building"],"mistakes":["Painting over damp walls without fixing source","Internal cementitious coating only (water pushes through)","Ignoring small seepage until structural steel rusts"],"diagnosis":"We map moisture ingress points, check slab cracks with NDT, and assess external grading. Hydrostatic pressure tests confirm whether water is entering from below or through walls.","linkedServices":["waterproofing","pu-injection","ndt"],"linkedProject":"hpcl-regional-facility","faqs":[{"q":"Can basement leakage damage columns?","a":"Yes. Persistent moisture corrodes column base reinforcement — weakening the entire structure silently."},{"q":"How long does basement waterproofing last?","a":"Proper external + internal system with crack repair typically lasts 10–15 years with maintenance."}]},{"slug":"terrace-roof-leakage","category":"roof","title":"Terrace & Roof Leakage","headline":"Terrace leaks that ruin ceilings below","intro":"Flat terrace roofs in Guwahati take brutal monsoon punishment. Standing water, failed waterproofing layers, and open expansion joints let water travel horizontally before dripping two floors below.","symptoms":["Ceiling stains directly under terrace","Peeling paint and bubbling plaster on top floor","Water dripping during heavy rain","Cracks at parapet wall junction"],"causes":["Aged bitumen or acrylic waterproofing layer","Improper slope — water ponds on terrace","Broken tile grout or open pipe penetration seals","Expansion joint failure between blocks"],"mistakes":["Temporary tarp or sealant patch each year","Adding another layer without removing failed membrane","Blocking terrace drains"],"diagnosis":"Flood test, infrared moisture scan, and visual inspection of parapet, drains, and penetrations. We trace water path before recommending terrace waterproofing system.","linkedServices":["waterproofing","expansion-joints","heatproofing"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"Should I retile or re-waterproof first?","a":"Always waterproof first. New tiles over a failed membrane waste money — leak returns next monsoon."}],"seoTitle":"Terrace leak repair Guwahati"},{"slug":"bathroom-seepage","category":"water-leakage","title":"Bathroom Seepage","headline":"Bathroom leaks affecting neighbours below","intro":"Bathroom seepage in apartment complexes is a top complaint in Guwahati RWA meetings. Water finds the weakest joint — often around WC pan, shower floor trap, or pipe sleeves.","symptoms":["Damp ceiling in flat below bathroom","Tile hollowness when tapped","Mould in grout lines","Persistent damp smell"],"causes":["Failed waterproofing under tile bed","Pipe sleeve not sealed at slab penetration","Cracked WC outlet or trap","No puddle flange at shower"],"mistakes":["Re-grouting tiles without lifting floor","Silicone around WC base as permanent fix","Ignoring neighbour complaint until legal notice"],"diagnosis":"Pressure test on plumbing lines, dye test on floor trap, and selective tile removal to inspect membrane continuity.","linkedServices":["waterproofing","pu-injection"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Do I need to break all bathroom tiles?","a":"Not always. Targeted removal at leak source plus PU injection at joints often suffices."}]},{"slug":"column-cracks","category":"cracks","title":"Column Cracks","headline":"Cracks in columns — when to worry","intro":"A crack in a partition wall is cosmetic. A crack running through a column in Seismic Zone V Guwahati is a structural red flag that demands immediate assessment.","symptoms":["Vertical or diagonal crack through column face","Crack width increasing over months","Concrete spalling exposing rusted steel","Crack at beam-column junction"],"causes":["Inadequate reinforcement or poor concrete pour","Settlement or differential movement","Corrosion-induced expansion of steel","Previous earthquake micro-damage"],"mistakes":["Filling with putty and painting","Ignoring because building is only 10 years old","Adding load (water tank, extension) without check"],"diagnosis":"Crack mapping, cover meter survey, rebound hammer, and ultrasonic pulse velocity. We classify active vs dormant cracks before prescribing CFRP wrap or injection.","linkedServices":["retrofitting","carbon-fibre","epoxy-injection","ndt"],"linkedProject":"dispur-government-office","faqs":[{"q":"Can I live in the building with column cracks?","a":"Depends on severity. Active widening cracks need urgent assessment — book inspection before next tremor season."}],"seoTitle":"Building column cracks in Guwahati"},{"slug":"wall-cracks","category":"cracks","title":"Wall Cracks","headline":"Structural vs non-structural wall cracks","intro":"Not every wall crack threatens your building. We help Guwahati homeowners tell the difference — and fix structural cracks before monsoon water reaches steel.","symptoms":["Stair-step cracks in masonry","Cracks wider than 3mm","Doors/windows sticking","Cracks at building corners"],"causes":["Thermal expansion without movement joints","Foundation settlement","Vibration from nearby construction","Load path changes after renovation"],"mistakes":["Treating all cracks the same","Plaster patch without crack stitching","Heavy tiling on compromised walls"],"diagnosis":"Crack width monitoring, plumb check, and load path review. Structural cracks get epoxy injection or stitching; cosmetic ones get flexible fillers.","linkedServices":["retrofitting","epoxy-injection"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"What crack width is dangerous?","a":"Cracks over 3mm in load-bearing walls, or any crack through a column/beam, need professional assessment."}],"seoTitle":"Building wall cracks in Guwahati"},{"slug":"damp-walls","category":"dampness","title":"Damp Walls & Peeling Paint","headline":"Why your walls stay damp after monsoon","intro":"Rising damp, lateral seepage, and internal condensation all look like \\"damp walls\\" — but each needs a different fix. Guwahati humidity makes this worse on ground and top floors.","symptoms":["Paint bubbling and peeling","Dark patches that spread in monsoon","Salt crystals on wall surface","Wall feels cold and wet to touch"],"causes":["No DPC (damp proof course) in older buildings","External wall seepage from adjacent bathroom/terrace","Capillary rise from ground","Poor ventilation on north-facing walls"],"mistakes":["Anti-damp paint without fixing source","Internal plastic membrane traps moisture","Running AC without addressing wall moisture"],"diagnosis":"Moisture meter profiling at multiple heights, external visual survey, and salt analysis to distinguish rising vs penetrating damp.","linkedServices":["waterproofing","pu-injection"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Does damp proof paint work?","a":"Only on surface condensation. Rising or lateral seepage needs waterproofing at source."}]},{"slug":"concrete-spalling","category":"cracks","title":"Concrete Spalling","headline":"Concrete falling off — exposed rusted steel","intro":"Spalling means steel inside concrete has rusted and expanded, bursting the cover. Common on Guwahati balconies, parapets, and coastal-exposed facades after years of monsoon.","symptoms":["Chunks of concrete falling off","Visible rust stains on facade","Exposed rebars on balcony slab edge","Hollow sound when tapping concrete"],"causes":["Insufficient concrete cover over steel","Chloride ingress from poor concrete mix","Water sitting on flat balcony edges","Carbonation reaching reinforcement depth"],"mistakes":["Patching with cement without treating steel","Leaving rebar exposed to rain","Ignoring balcony edge spalling as cosmetic"],"diagnosis":"Half-cell potential for corrosion activity, cover depth survey, and delamination mapping. Steel is cleaned, treated, and reinstated with repair mortar.","linkedServices":["retrofitting","epoxy-injection","carbon-fibre"],"linkedProject":"dispur-government-office","faqs":[{"q":"Is spalling urgent?","a":"Yes. Exposed steel corrodes rapidly — load capacity drops and concrete can fall on people below."}]},{"slug":"foundation-settlement","category":"foundation","title":"Foundation Settlement","headline":"Uneven floors and sticking doors — settlement signs","intro":"Guwahati soil varies from stiff clay to soft alluvium. Buildings on filled land or near Bharalu basin streams often show settlement years after construction.","symptoms":["Sloping floors","Doors and windows not closing","Cracks at window corners","Gaps between floor and skirting"],"causes":["Consolidation of soft soil under load","Poor compaction during construction","Water table changes","Nearby excavation"],"mistakes":["Jack-up floors without addressing soil","Heavy extension on unsettled foundation","Ignoring tilting as \\"normal\\""],"diagnosis":"Level survey, crack pattern analysis, and borehole data where needed. Underpinning or grouting prescribed based on settlement mechanism.","linkedServices":["retrofitting","pu-injection","ndt"],"linkedProject":"industrial-warehouse-paltan-bazar","faqs":[{"q":"Can settlement be stopped?","a":"Often yes — with pressure grouting or underpinning once cause is confirmed."}]},{"slug":"roof-waterproofing-failure","category":"roof","title":"Failed Roof Waterproofing","headline":"When your waterproofing layer has given up","intro":"Most Guwahati terraces have 2–3 failed waterproofing attempts layered on top of each other. Heat, UV, and ponding water degrade membranes within 5–8 years if not maintained.","symptoms":["Multiple repair patches visible on terrace","Membrane bubbling or peeling","Green moss growth on terrace surface","Leak returns within one monsoon of repair"],"causes":["Wrong system for traffic load","No protection screed over membrane","Penetration details poorly done","Thermal cycling in black exposed membrane"],"mistakes":["Cheap local contractor re-coat annually","Using interior paint on exterior terrace","Not fixing slope before new membrane"],"diagnosis":"Core samples where possible, adhesion tests, and drainage assessment. Full system redesign vs localized repair decided on inspection.","linkedServices":["waterproofing","heatproofing","expansion-joints"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"Which waterproofing lasts longest on terraces?","a":"PU liquid membrane or multilayer bituminous with protection tile — depends on traffic and budget."}]},{"slug":"expansion-joint-leakage","category":"water-leakage","title":"Expansion Joint Leakage","headline":"Water pouring through building expansion joints","intro":"Multi-block apartment complexes in Guwahati rely on expansion joints to move safely — but failed joint seals become highways for monsoon water into parking and flats.","symptoms":["Water through joint during rain","Stains along joint line on ceiling","Joint filler cracked or missing","Leak at podium level parking"],"causes":["Aged joint sealant lost elasticity","Wrong joint profile for movement","Debris in joint preventing seal","Structural movement exceeding design"],"mistakes":["Silicone fill without joint preparation","Rigid material in a moving joint","Ignoring parking level joint leaks"],"diagnosis":"Joint width measurement across seasons, movement assessment, and water test. Proper joint system selected for actual movement range.","linkedServices":["expansion-joints","waterproofing","pu-injection"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Can expansion joints be made 100% watertight?","a":"With correct profile, backing rod, and flexible sealant — yes, for designed movement range."}]},{"slug":"basement-dampness","category":"dampness","title":"Basement Dampness","headline":"Damp basement without visible flooding","intro":"Even without standing water, basements in Guwahati commercial buildings suffer high humidity from capillary rise and poor vapour barriers — damaging inventory and HVAC.","symptoms":["High humidity readings","Condensation on pipes and walls","Mould on cardboard storage","Sweating floor slab"],"causes":["No vapour barrier under slab","High water table wicking through slab","Poor ventilation","Leaking underground pipes"],"mistakes":["Dehumidifier only — treats symptom","Sealing walls trapping moisture inside","No sub-soil drainage"],"diagnosis":"Hygrometer logging, slab moisture test, and drainage survey. Internal tanking vs external cutoff depends on access and water table.","linkedServices":["waterproofing","pu-injection"],"linkedProject":"hpcl-regional-facility","faqs":[{"q":"Is basement dampness a health issue?","a":"Yes — mould affects air quality. Commercial basements need humidity control plus source fix."}]},{"slug":"parapet-leakage","category":"roof","title":"Parapet Wall Leakage","headline":"Leaks at parapet — the most missed terrace detail","intro":"Water enters where parapet wall meets terrace slab — a detail often skipped by local waterproofers. In Guwahati high-rises, this causes chronic top-floor ceiling damage.","symptoms":["Stains along top floor exterior wall","Leak at ceiling-wall junction","Cracks at parapet base","Rust stains on exterior facade"],"causes":["No kick-out flashing at parapet base","Parapet masonry porous","Coping tiles cracked","Inadequate height for wind-driven rain"],"mistakes":["Only coating terrace flat area","Ignoring parapet coping cracks","Low parapet height in wind zone"],"diagnosis":"Visual and flood test focused on parapet upturn, coping, and counter-flashing details.","linkedServices":["waterproofing","expansion-joints"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"Do I need to rebuild parapet?","a":"Rarely. Proper upturn membrane and coping repair usually fixes it."}]},{"slug":"beam-column-junction-cracks","category":"cracks","title":"Beam-Column Junction Cracks","headline":"Cracks where beam meets column — seismic risk","intro":"The beam-column joint is where earthquake forces concentrate. Hairline cracks here in older Guwahati RCC frames may indicate inadequate confinement steel.","symptoms":["X-shaped cracks at joints","Cracks after tremor felt","Plaster damage at corners","Building age 20+ years, pre-IS 13920"],"causes":["Non-ductile detailing in old design","Corrosion at joint","Overloading","Previous seismic event damage"],"mistakes":["Cosmetic plaster repair","No post-earthquake inspection","Adding floors without joint check"],"diagnosis":"Structural audit per IS codes, NDT on joint zone, and seismic vulnerability screening.","linkedServices":["retrofitting","carbon-fibre","epoxy-injection"],"linkedProject":"dispur-government-office","faqs":[{"q":"Are joint cracks always serious?","a":"In Zone V, yes — treat as structural until proven otherwise."}]},{"slug":"water-tank-leakage","category":"water-leakage","title":"Overhead Tank Leakage","headline":"Overhead tank leaks wasting water and weakening slabs","intro":"Overhead tanks on Guwahati rooftops often leak at panel joints and pipe connections — saturating slab below and adding dead load from stored water.","symptoms":["Water dripping from slab soffit","Tank refilling more often","Wet patch on terrace under tank","Rust at tank support frame"],"causes":["Failed tank panel sealant","Overflow pipe wrongly connected","Cracked tank base slab","Corroded support structure"],"mistakes":["External tank wrap without fixing joint","Ignoring overflow wastage","Extra tank load without slab check"],"diagnosis":"Tank empty inspection, slab capacity review, and support corrosion check.","linkedServices":["waterproofing","retrofitting","pu-injection"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Can slab hold a new larger tank?","a":"Needs structural check — many older slabs were not designed for extra tank capacity."}]},{"slug":"external-wall-seepage","category":"dampness","title":"External Wall Seepage","headline":"Rain water soaking through external walls","intro":"Guwahati driving monsoon rain hits exposed west and south facades. Cracks in external plaster, failed paint, and open chajja joints let water into bedroom walls.","symptoms":["Interior damp on external walls only","Worse during wind-driven rain","Algae on exterior plaster","Paint failure on sun-exposed side"],"causes":["Micro-cracks in exterior coating","No water repellent on porous brick","Chajja drip edge missing","Window frame seal failure"],"mistakes":["Internal waterproofing paint only","Closing weep holes","Cheap exterior emulsion on bare brick"],"diagnosis":"Facade survey, window percolation test, and coating adhesion check.","linkedServices":["waterproofing","pu-injection"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"Silicone coating vs proper plaster repair?","a":"Coating is temporary on cracked substrate. Crack repair + breathable coating lasts longer."}]},{"slug":"slab-leakage","category":"water-leakage","title":"Slab Leakage","headline":"Water travelling through concrete slabs","intro":"Hidden slab leaks from embedded pipes or honeycombed concrete cause ceiling damage far from the source — common in Guwahati bathrooms and kitchens.","symptoms":["Random ceiling damp spots","Water meter running when taps off","Warm spot on floor (hot pipe leak)","Hollow sound in slab"],"causes":["Embedded pipe corrosion","Honeycomb in slab pour","Post-tension duct leakage","Drilling into concealed pipe"],"mistakes":["Breaking random ceiling areas","Ignoring small seepage","No pressure test before retiling"],"diagnosis":"Thermal imaging, acoustic leak detection, and selective core test.","linkedServices":["pu-injection","epoxy-injection","waterproofing"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Can PU injection fix slab leaks?","a":"Yes for porous concrete and some joint leaks — not for burst pipes (plumbing fix needed first)."}]},{"slug":"corrosion-in-concrete","category":"cracks","title":"Steel Corrosion in Concrete","headline":"Rust inside concrete — silent strength loss","intro":"Carbonation and chloride attack reach steel in Guwahati coastal-influenced climate. Corrosion can consume 40% of bar strength before visible spalling.","symptoms":["Rust stains without visible crack","Cover concrete sounding hollow","Early spalling on balcony","Building near Brahmaputra humidity"],"causes":["Low cover concrete","Poor quality sand/ water","Leak keeping concrete wet","Marine aerosol in some zones"],"mistakes":["Waiting for spalling to act","Patch without passivating steel","No ongoing monitoring"],"diagnosis":"Half-cell, cover meter, and chloride sampling. Remaining life estimated before repair scope.","linkedServices":["retrofitting","epoxy-injection","ndt"],"linkedProject":"hpcl-regional-facility","faqs":[{"q":"Can corrosion be reversed?","a":"Steel can be treated and re-passivated; lost section needs supplemental reinforcement."}]},{"slug":"parking-basement-leakage","category":"water-leakage","title":"Parking Basement Leakage","headline":"Water in stilt parking every monsoon","intro":"Stilt parking in Guwahati apartment projects often leaks at podium slab joints and ramp entrances — damaging vehicles and electrical panels.","symptoms":["Puddles in parking after rain","Efflorescence on columns at parking level","Leak at ramp entrance","Dripping from expansion joints"],"causes":["Podium waterproofing failure","Ramp without water stop","Inadequate storm drain capacity","Planter boxes above parking leaking"],"mistakes":["Channeling water without fixing slab","Covering joints with boards","Ignoring electrical safety near water"],"diagnosis":"Podium flood test, joint inspection, and drainage flow assessment.","linkedServices":["waterproofing","expansion-joints","pu-injection"],"linkedProject":"chandmari-apartment-complex","faqs":[{"q":"Can parking be used during repair?","a":"Phased repair possible — we section off bays to minimize disruption."}]},{"slug":"mould-and-fungus","category":"dampness","title":"Mould & Fungus Growth","headline":"Mould on walls — sign of deeper moisture problem","intro":"Mould in Guwahati flats is not just cleaning issue. It signals persistent moisture from leak, rising damp, or poor ventilation — affecting respiratory health.","symptoms":["Black/green patches in corners","Musty smell returns after cleaning","Mould on clothes in wardrobe","Worse in monsoon months"],"causes":["Hidden leak maintaining humidity","No exhaust in bathroom/kitchen","Cold bridge condensation","Ground floor rising damp"],"mistakes":["Bleach wash only","Sealing room without ventilation","Ignoring HVAC mould in offices"],"diagnosis":"Moisture source tracing, air quality check, and ventilation assessment.","linkedServices":["waterproofing","pu-injection"],"linkedProject":"beltola-residential-tower","faqs":[{"q":"Will mould come back after cleaning?","a":"Always, until moisture source is fixed."}]},{"slug":"structural-weakness-old-buildings","category":"cracks","title":"Weak Structure in Old Buildings","headline":"Is your 30-year-old Guwahati building still safe?","intro":"Many Guwahati buildings pre-2000 were built before modern seismic codes. Age, corrosion, and illegal modifications compound structural weakness.","symptoms":["Multiple columns with cracks","Visible building sway feeling","Illegal terrace room added","Frequent plaster cracks reappearing"],"causes":["Code evolution — older designs under-designed","Corrosion over decades","Unauthorized load additions","No periodic structural audit"],"mistakes":["Buying resale without NDT","RWA delaying mandatory audit","Trusting builder verbal assurance"],"diagnosis":"Full structural health assessment — NDT suite, load take-down, and seismic screening report.","linkedServices":["ndt","retrofitting","carbon-fibre"],"linkedProject":"dispur-government-office","faqs":[{"q":"How often should old buildings be assessed?","a":"Every 5 years for 25+ year buildings in Zone V — more if cracks appear."}]}],"industries":[],"knowledgeArticles":[{"slug":"what-causes-terrace-leaks-guwahati","cluster":"waterproofing","title":"What causes terrace leaks in Guwahati?","excerpt":"Monsoon, flat roofs, and failed membranes — why terrace leaks are so common in Northeast India.","body":"Guwahati receives over 1,600mm rainfall annually, mostly concentrated in monsoon months. Flat terrace design — standard in apartment construction — allows water to pond if slope is inadequate. Over time, UV and heat cycling degrade waterproofing membranes. Penetrations around pipes and parapet upturns fail first. The fix starts with diagnosis: flood test and tracing water path before any new coating."},{"slug":"column-crack-vs-settlement-crack","cluster":"structural","title":"Column crack vs settlement crack — how to tell","excerpt":"Not all cracks are equal. Learn which patterns need urgent structural attention.","body":"Settlement cracks often appear as stair-steps in masonry or diagonal cracks at window corners. Column cracks run through the concrete member itself — often vertical or at beam-column joints. Width matters: cracks over 3mm in structural members warrant professional assessment. In Seismic Zone V, any column crack should be inspected before the next tremor season."},{"slug":"pu-injection-vs-epoxy-injection","cluster":"injection","title":"PU injection vs epoxy injection — when to use which","seoTitle":"PU vs epoxy injection — when to use which","excerpt":"Both fill cracks — but they work differently. Choosing wrong wastes money.","body":"PU (polyurethane) injection reacts with water to expand — ideal for active leaking cracks in basements and terraces. Epoxy injection bonds concrete structurally — used for dry structural cracks in columns and beams where strength restoration is needed. Many projects need both: PU to stop water, epoxy to restore capacity."},{"slug":"carbon-fibre-wrap-explained","cluster":"retrofitting","title":"Carbon fibre wrapping explained for homeowners","excerpt":"CFRP adds strength without bulky columns — how it works on Guwahati flats.","body":"Carbon fibre reinforced polymer (CFRP) sheets are epoxy-bonded to concrete surfaces. They add tensile capacity to weakened columns and beams with minimal thickness — important in occupied flats where space matters. It is not a paint product; surface prep and structural design are critical."},{"slug":"ndt-before-buying-resale-flat","cluster":"ndt","title":"Why get NDT before buying a resale flat in Guwahati","seoTitle":"NDT before buying a resale flat","excerpt":"Hidden defects cost lakhs after purchase. A building strength test is cheap insurance.","body":"Rebound hammer, UPV, and cover meter tests reveal honeycomb, low strength concrete, and corroding steel — invisible during a normal flat viewing. In Beltola and Chandmari resale markets, 15–30 year buildings often have monsoon damage. NDT report gives negotiation leverage or avoids a bad purchase."},{"slug":"rising-damp-vs-lateral-seepage","cluster":"waterproofing","title":"Rising damp vs lateral seepage","excerpt":"Both cause damp walls — but fixing the wrong one fails next monsoon.","body":"Rising damp shows up to 1m from floor — salt deposits, tide marks. Lateral seepage from adjacent bathroom or external wall affects mid-height patches. Ground floor flats in old Guwahati buildings often have both. Moisture meter profiling at multiple heights distinguishes them."},{"slug":"expansion-joints-apartment-buildings","cluster":"waterproofing","title":"Expansion joints in apartment buildings — why they leak","seoTitle":"Apartment expansion joint leaks","excerpt":"Movement joints are necessary — but failed seals flood parking levels.","body":"Multi-block complexes need joints to absorb thermal and seismic movement. Sealant loses elasticity after 5–7 years. Rigid fillers crack. Proper repair uses correct joint width, backing rod, and movement-capable sealant — not cheap silicone."},{"slug":"seismic-zone-5-guwahati-homeowner","cluster":"retrofitting","title":"Seismic Zone V — what Guwahati homeowners should know","seoTitle":"Seismic Zone V — Guwahati homeowners","excerpt":"Highest earthquake zone in India. What it means for your building.","body":"Guwahati sits in IS seismic Zone V. Older buildings may not meet current ductile detailing standards. Retrofitting — column jacketing, CFRP, joint confinement — reduces collapse risk. It is not optional luxury; it is risk management for your family."},{"slug":"basement-waterproofing-methods","cluster":"waterproofing","title":"Basement waterproofing methods compared","excerpt":"Internal tanking, external membrane, injection — which suits Guwahati soil?","body":"High water table areas need external cutoff where accessible. Internal crystalline systems work when excavation is impossible. PU injection handles active leaks through cracks. Often a combination is required — diagnosis determines sequence."},{"slug":"concrete-spalling-early-signs","cluster":"structural","title":"Concrete spalling — catch it before chunks fall","excerpt":"Rust stains and hollow sounds are warnings. Act before balcony edges fail.","body":"Spalling starts when steel corrodes inside concrete. Early signs: rust staining, fine cracks parallel to rebar, hollow sound when tapped. Patch repair without steel treatment fails in one monsoon. Proper repair: expose, clean, treat, reinstate with structural mortar."},{"slug":"heat-reflective-roof-coating","cluster":"heatproofing","title":"Heat reflective roof coating — does it work in Assam?","excerpt":"Weather Cool and similar coatings — real temperature drop or marketing?","body":"Reflective coatings reduce surface temperature by up to 14°C on exposed terraces. They also extend underlying waterproofing life by reducing thermal stress. Best applied on stable substrate after leak repair — not over active leaks."},{"slug":"structural-audit-vs-home-inspection","cluster":"ndt","title":"Structural audit vs home inspection","excerpt":"Property inspectors miss structural issues. Know the difference.","body":"Home inspection checks plumbing, electrical, and cosmetics. Structural audit uses NDT, crack mapping, and load review. For resale flats and old commercial buildings in Guwahati, structural audit is the relevant standard."},{"slug":"monsoon-building-maintenance-checklist","cluster":"maintenance","title":"Monsoon building maintenance checklist","excerpt":"Pre-monsoon steps every Guwahati building owner should take.","body":"Clear terrace drains. Inspect parapet and pipe penetrations. Check expansion joints. Look for new cracks in columns. Test overhead tank overflows. Book professional inspection if building is 15+ years or shows any structural crack."},{"slug":"rwa-terrace-waterproofing-decisions","cluster":"waterproofing","title":"RWA guide: terrace waterproofing decisions","excerpt":"How housing societies should evaluate contractor quotes fairly.","body":"Compare methodology not just price. Ask: membrane type, slope correction, penetration detail, warranty, and flood test protocol. Cheapest quote often skips parapet upturn and joint treatment — leak returns in one season."},{"slug":"illegal-terrace-room-structural-risk","cluster":"structural","title":"Illegal terrace rooms — structural risk","excerpt":"Extra load on terrace slab can exceed design capacity.","body":"Many Guwahati buildings have unauthorized terrace rooms. Slab may not be designed for additional dead load. Combined with waterproofing failure, risk is significant. Structural check before any terrace use modification."},{"slug":"epoxy-flooring-industrial-warehouses","cluster":"industrial","title":"Epoxy flooring for industrial warehouses","excerpt":"When concrete dust and forklift traffic need industrial grade floors.","body":"Epoxy and polyurethane floor systems handle abrasion, chemical spill, and heavy point loads. Surface prep — grinding and moisture test — determines adhesion. Paltan Bazar and outskirts warehouses benefit from phased bay application."},{"slug":"borewell-recharge-rainwater-harvesting","cluster":"sustainability","title":"Borewell recharge and rainwater harvesting in Guwahati","seoTitle":"Rainwater harvesting in Guwahati","excerpt":"Heavy rain, falling groundwater — capture and recharge responsibly.","body":"Rooftop rainwater can flush toilets and recharge borewells via soak pits — if soil and contamination risks are assessed. Reduces water bill and helps maintain groundwater in urban Guwahati."},{"slug":"faq-building-leaks-ai-summary","cluster":"ai-seo","title":"Building leak FAQ — quick answers for Guwahati","excerpt":"Common questions about leaks, cracks, and repair costs.","body":"Q: Who fixes basement leaks in Guwahati? A: Building rehabilitation specialists with waterproofing and injection capability — not general painters. Q: Cost? A: Depends on diagnosis — inspection first. Q: How long? A: Terrace systems 7–14 days; column retrofit varies."},{"slug":"micro-concreting-honeycomb-repair","cluster":"retrofitting","title":"Micro concreting for honeycomb repair","excerpt":"Hollow columns sound bad — micro concreting fills voids without demolition.","body":"Honeycomb in columns leaves steel unprotected. High-strength grout injection fills voids. Used with NDT confirmation. Common in buildings with rushed pours during original construction boom."},{"slug":"when-to-call-building-doctor","cluster":"general","title":"When to call a building doctor vs a contractor","excerpt":"Symptoms vs root cause — who should you call first?","body":"Call a contractor when you know the fix: new tiles, paint job. Call a building rehabilitation specialist when you have symptoms — leak, crack, damp — but unknown cause. Diagnosis-first approach saves money long term."},{"slug":"waterproofing-contractor-guwahati-how-to-choose","cluster":"waterproofing","title":"How to choose a waterproofing contractor in Guwahati","seoTitle":"Waterproofing contractor Guwahati","excerpt":"Red flags, fair quotes, and what a proper terrace job includes.","body":"Compare methodology, not just per-sq-ft price. A proper Guwahati terrace job includes drain clearance, slope check, parapet upturn, penetration seals, and flood test — not a single acrylic coat. Ask for warranty in writing, previous society references in Beltola or Chandmari, and whether they diagnose before quoting. Avoid contractors who guarantee a fixed rate without site visit.","linkedServices":["waterproofing","pu-injection","expansion-joints"]},{"slug":"building-crack-repair-cost-guwahati","cluster":"structural","title":"Building crack repair cost in Guwahati — what to expect","seoTitle":"Building crack repair cost Guwahati","excerpt":"Cosmetic plaster vs structural column repair — very different budgets.","body":"Hairline wall crack filling may cost a few thousand rupees. Structural work — crack mapping, NDT, epoxy injection, CFRP wrap on columns — can run from ₹50,000 for a single member to several lakhs for a building wing. Guwahati Zone V buildings should not treat column cracks as cosmetic. Always get inspection before comparing quotes.","linkedServices":["retrofitting","ndt","epoxy-injection","carbon-fibre"],"linkedProblems":["column-cracks","wall-cracks"]},{"slug":"seismic-retrofitting-cost-guwahati","cluster":"retrofitting","title":"Seismic retrofitting cost in Guwahati — 2026 guide","seoTitle":"Retrofitting cost in Guwahati","excerpt":"CFRP, jacketing, and NDT — what drives price for Guwahati homes.","body":"Retrofitting cost depends on member count, access, and strength deficit found in NDT. CFRP column wrap on a typical residential column may start around ₹15,000–40,000 per member; full building screening plus multiple jackets scales higher. Cheaper than emergency repair after damage — and far cheaper than life risk in Zone V.","linkedServices":["retrofitting","seismic-jacketing","carbon-fibre","ndt"]},{"slug":"monsoon-roof-leak-guwahati","cluster":"waterproofing","title":"Monsoon roof leak in Guwahati — causes and fix","excerpt":"Why flat terraces leak every monsoon in Guwahati and what actually fixes them — not another paint coat.","body":"Guwahati gets over 1,600 mm of rain, mostly between May and September. Most apartment terraces are flat RCC slabs — water ponds if slope is wrong, then finds the weakest joint: pipe penetrations, parapet upturns, or old bitumen layers cracked by heat.\\n\\nCommon causes we see in Beltola, Chandmari, and Six Mile: failed waterproofing membrane under tiles, blocked terrace drains, expansion joint gaps between blocks, and parapet base details done wrong the first time.\\n\\nTemporary fixes — silicone, tarp, local contractor re-coat — fail within one monsoon because water travels horizontally under the surface before dripping two floors below.\\n\\nProper fix starts with diagnosis: flood test, tracing the water path, checking drains and parapet. Then either localized PU injection for active cracks or full terrace waterproofing system with protection layer.\\n\\nCost depends on terrace area, existing failed layers, and whether tiles must be lifted. We quote after a free site inspection — not over WhatsApp.\\n\\nIf your ceiling stains every monsoon, book an inspection before the next heavy spell. Catching it early saves structural steel from rust inside the slab."},{"slug":"flat-crack-repair-cost-guwahati","cluster":"structural","title":"Flat crack repair cost in Guwahati — what affects price","excerpt":"Hairline plaster crack vs structural column crack — very different costs. Here''s what drives price in Guwahati flats.","body":"Not every crack costs the same. A stair-step crack in partition plaster might be ₹5,000–15,000 to repair properly. A crack through a column or beam in Seismic Zone V can run into lakhs if CFRP wrapping, injection, and NDT are needed.\\n\\nPrice drivers: crack width and length, whether steel is exposed or corroding, number of cracks, floor access (scaffolding for high-rise), and whether the crack is active (still widening) or dormant.\\n\\nNDT — rebound hammer, UPV, cover meter — adds ₹15,000–40,000 depending on building size but prevents guessing. Many Guwahati resale buyers in Beltola and Zoo Road use this before purchase.\\n\\nEpoxy injection for dry structural cracks: typically ₹800–2,500 per running metre depending on depth and access. PU injection for leaking cracks: similar range but may need multiple passes.\\n\\nWe don''t give accurate quotes without seeing the crack in person. Photos help for triage, not pricing. Free inspection first — we''ll tell you honestly if it''s cosmetic, monitor-only, or urgent.\\n\\nWaiting until monsoon water reaches steel inside the column often doubles repair cost. Book inspection early if the crack is in a column, beam, or load-bearing wall."},{"slug":"terrace-waterproofing-cost-guwahati","cluster":"waterproofing","title":"Terrace waterproofing cost in Guwahati (2026 guide)","excerpt":"Terrace waterproofing prices in Guwahati depend on area, system, and how many failed layers are underneath — honest ranges after inspection.","body":"Terrace waterproofing in Guwahati typically runs ₹80–150 per sq ft for a proper liquid membrane system on a standard flat terrace — but that''s a range, not a quote. Top-floor flats with heavy tile, multiple old failed coats, or parapet rebuild needs can go higher.\\n\\nWhat affects price: terrace area (sq ft), whether existing tiles must be broken and removed, number of failed waterproofing layers already stacked, parapet and drain detail work, heat-reflective top coat (Weather Cool), and whether PU injection is needed at cracks first.\\n\\nCheap ₹40/sq ft acrylic coats fail within 1–2 monsoons on exposed Guwahati terraces — we''ve removed three failed layers on a single Beltola tower. Proper system includes surface prep, primer, membrane, protection screed or tiles, and detail work at pipes and walls.\\n\\nMonsoon timing matters: full membrane application needs dry windows between showers. Emergency leak-stopping with PU injection can happen during rain; full recoating usually waits for a dry spell.\\n\\nWe always inspect before quoting. No accurate price over phone or WhatsApp without seeing terrace condition, ponding areas, and existing layers.\\n\\nIf you''re comparing contractors, ask what''s included: drain cleaning, parapet upturn, pipe collar seals, and warranty length. Book a free inspection for a written scope and honest price range."}],"homeownerFaq":{"eyebrow":"FAQ","headline":"Common questions before you call","items":[{"q":"Do you waterproof tin or GI sheet roofs?","a":"No. We waterproof concrete — RCC terrace slabs, bathrooms, basements, and podiums. Tin, GI, CGI, and asbestos sheet roofs are a different trade. If your leak is on a pucca concrete terrace or through a bathroom slab, we can help.","link":{"href":"/services/waterproofing","label":"What we waterproof →"}},{"q":"What is retrofitting — and do I need it?","a":"Retrofitting means making the columns and beams you already have stronger so they survive the next tremor. Guwahati is Zone V. Call us if a crack runs through a column, comes back after paint, or appeared after a tremor — not for a hairline crack in plaster between rooms.","link":{"href":"/services/retrofitting","label":"When to strengthen →"}},{"q":"Why test a building before buying or repairing?","a":"Paint hides hollow or weak concrete. A building strength test is an X-ray for columns without breaking them open (NDT). Get it before you sign a resale deal, and before you spend on strengthening — so the repair matches the actual weakness. It is not a substitute for repair.","link":{"href":"/services/ndt","label":"Building strength test →"}},{"q":"How much does waterproofing cost?","a":"Depends on area, leak severity, and whether it is a concrete terrace, bathroom, or basement. A typical Guwahati RCC terrace starts around ₹80–150 per sq ft for proper membrane work — we quote after inspection, not over the phone. Free site visit first. Not for tin roofs.","link":{"href":"/services/waterproofing","label":"Waterproofing services →"}},{"q":"How long does an inspection take?","a":"Most home inspections take 45–90 minutes. We check the problem area, trace water paths or crack patterns, and explain findings in plain language. You get a clear recommendation — repair now, monitor, or no action needed.","link":{"href":"/contact#inspection-form","label":"Book free inspection →"}},{"q":"Do you work during monsoon season?","a":"Yes — monsoon is when most Guwahati homeowners notice leaks. Emergency leak-stopping (PU injection) can be done during rain. Full concrete-terrace waterproofing is usually scheduled between showers so the membrane bonds properly.","link":{"href":"/problems/terrace-roof-leakage","label":"Terrace leak guide →"}}]},"contactTeaser":{"ctaLabel":"Book inspection","ctaHref":"/contact#inspection-form"},"googleReviewsData":{"profileUrl":"https://maps.app.goo.gl/ogPYnKhJLep1R5hD9","businessName":"91Skylineworks pvt ltd.","rating":5,"reviewCount":13,"reviews":[{"authorName":"Karanjal Das","rating":5,"text":"Very good service, value for money with best quality.","relativeTime":"4 years ago","snapshot":"/images/reviews/review-karanjal-das.webp","snapshotAlt":"Google review by Karanjal Das — 5 stars"},{"authorName":"Rupjyoti Barkataki","rating":5,"text":"Very impressive and good quality or quick response with Excellent service","relativeTime":"3 years ago","snapshot":"/images/reviews/review-rupjyoti-barkataki.webp","snapshotAlt":"Google review by Rupjyoti Barkataki — 5 stars"},{"authorName":"Sthapana Sharma","rating":5,"text":"Responsiveness, Punctuality, Quality, Professionalism, Value","relativeTime":"4 years ago","snapshot":"/images/reviews/review-sthapana-sharma.webp","snapshotAlt":"Google review by Sthapana Sharma — 5 stars"},{"authorName":"tanushree basnet","rating":5,"text":"Professionalism","relativeTime":"5 years ago","snapshot":"/images/reviews/review-tanushree-basnet.webp","snapshotAlt":"Google review by tanushree basnet — 5 stars"},{"authorName":"swayam prava","rating":5,"text":"Responsiveness, Punctuality, Quality, Professionalism, Value","relativeTime":"5 years ago","snapshot":"/images/reviews/review-swayam-prava.webp","snapshotAlt":"Google review by swayam prava — 5 stars"},{"authorName":"Amit Nath","rating":5,"text":"Responsiveness, Punctuality, Quality, Professionalism, Value","relativeTime":"5 years ago","snapshot":"/images/reviews/review-amit-nath.webp","snapshotAlt":"Google review by Amit Nath — 5 stars"},{"authorName":"Manasi Bora","rating":5,"text":"Responsiveness, Quality, Professionalism","relativeTime":"5 years ago","snapshot":"/images/reviews/review-manasi-bora.webp","snapshotAlt":"Google review by Manasi Bora — 5 stars"},{"authorName":"RAVI RANJAN","rating":5,"text":"","relativeTime":"4 years ago","snapshot":"/images/reviews/review-ravi-ranjan.webp","snapshotAlt":"Google review by RAVI RANJAN — 5 stars"}]},"serviceCategories":[{"slug":"retrofitting","label":"Retrofitting","headline":"Earthquake strengthening for Guwahati homes","intro":"Seismic Zone V retrofitting — CFRP wrapping, jacketing, structural repairs, and concrete restoration for columns, beams, and foundations. Older RCC loses strength with time; retrofit before the next tremor, not after collapse.","seoTitle":"Retrofitting in Guwahati"},{"slug":"waterproofing","label":"Waterproofing","headline":"Stop leaks before monsoon damage spreads","intro":"Terrace, bathroom, basement, and joint waterproofing — plus PU injection and expansion joint treatment across Guwahati.","seoTitle":"Waterproofing services in Guwahati"},{"slug":"ndt","label":"NDT Testing","headline":"Know your building''s strength before you buy or repair","intro":"Non-destructive building strength tests for resale flats, old RCC frames, and pre-retrofit assessment in Northeast India. Other states mandate periodic audits on ageing buildings — Guwahati owners should not wait for law to catch up."},{"slug":"heatproofing","label":"Heatproofing","headline":"Cooler top floors in Guwahati summers","intro":"Heat-reflective roof coatings that cut surface temperature and reduce AC load on terrace slabs."},{"slug":"rainwater-harvesting","label":"Rain Water Harvesting","headline":"Capture Guwahati''s monsoon rain on your roof","intro":"Rooftop rainwater harvesting and borewell recharge systems for homes and societies in Assam."}],"navServices":[{"label":"Waterproofing in Guwahati","href":"/guwahati/waterproofing"},{"label":"Building crack repair","href":"/guwahati/building-crack-repair"},{"label":"Retrofitting in Guwahati","href":"/services/retrofitting"},{"label":"Retrofitting","href":"/services/category/retrofitting"},{"label":"Waterproofing","href":"/services/category/waterproofing"},{"label":"NDT Testing","href":"/services/category/ndt"},{"label":"Heatproofing","href":"/services/category/heatproofing"},{"label":"Rain Water Harvesting","href":"/services/category/rainwater-harvesting"}],"localLandings":[{"slug":"waterproofing","seoTitle":"Waterproofing in Guwahati","headline":"Waterproofing in Guwahati","intro":"Terrace leaks, bathroom seepage, and basement damp are the top monsoon complaints we see across Beltola, Chandmari, Hatigaon, and Dispur. 91SkylineWorks diagnoses the water path first — then specifies membrane, PU injection, or joint repair that lasts beyond one season.","serviceSchemaName":"Waterproofing in Guwahati","sections":[{"title":"Terrace & roof waterproofing","body":"Flat terraces need correct slope, parapet upturn, and a membrane suited to foot traffic. We flood-test before coating — patching over ponding water fails every monsoon."},{"title":"Bathroom & kitchen slab leaks","body":"Inter-floor seepage in apartment blocks often starts at trap penetrations or failed tile-bed membranes. Targeted repair avoids breaking every tile when diagnosis is precise."},{"title":"Basement & plinth waterproofing","body":"Guwahati''s shallow water table pushes hydrostatic pressure through ground floors in Ulubari, Bhangagarh, and low-lying plots. Internal tanking, external cutoff, or PU injection depends on access and soil."},{"title":"Typical cost range","body":"Terrace waterproofing for a Guwahati flat often runs ₹80–150 per sq ft after inspection — varies with area, leak severity, slope correction, and protection course. We quote after site visit, not over WhatsApp guesses."}],"linkedServices":["waterproofing","pu-injection","expansion-joints","heatproofing"],"linkedProblems":["terrace-roof-leakage","bathroom-seepage","basement-water-leakage"],"faqs":[{"q":"Who does waterproofing in Guwahati?","a":"Look for building rehabilitation specialists who diagnose first — not painters offering a single coat. Proper work includes slope, penetrations, parapet details, and flood test."},{"q":"How long does terrace waterproofing take?","a":"Most residential terraces take 7–14 days including surface prep, membrane cure time, and protection course — weather dependent."},{"q":"Can waterproofing be done during monsoon?","a":"Emergency leak-stopping with PU injection can run in rain. Full membrane work is usually scheduled between monsoons for best adhesion."}],"ctaMessage":"Monsoon leak? Book a free inspection — we''ll trace the water path before quoting."},{"slug":"building-crack-repair","seoTitle":"Building crack repair in Guwahati","headline":"Building crack repair in Guwahati","intro":"A crack in a partition wall is often cosmetic. A crack through a column in Seismic Zone V is not. We help Guwahati homeowners and RWAs tell the difference — then repair with crack mapping, NDT, epoxy injection, CFRP wrap, or jacketing as the structure requires.","serviceSchemaName":"Building crack repair in Guwahati","sections":[{"title":"Column & beam-column cracks","body":"Vertical or diagonal cracks through columns and X-patterns at beam-column joints need urgent assessment in Zone V. Putty and paint hide risk — they do not restore capacity."},{"title":"Wall cracks — structural vs cosmetic","body":"Stair-step cracks in masonry, cracks wider than 3mm, or doors that stick may indicate settlement or load-path change. We monitor width and prescribe stitching, injection, or flexible fillers accordingly."},{"title":"Retrofitting after diagnosis","body":"When NDT shows lost strength, we specify CFRP wrapping, micro concreting for honeycomb, or seismic jacketing — not a one-size contractor template."},{"title":"Areas we serve","body":"Residential towers in Beltola and Chandmari, institutional blocks in Dispur and Six Mile, and commercial buildings on GS Road — anywhere Guwahati RCC needs honest structural assessment."}],"linkedServices":["retrofitting","ndt","epoxy-injection","carbon-fibre","seismic-jacketing"],"linkedProblems":["column-cracks","wall-cracks","beam-column-junction-cracks","concrete-spalling"],"faqs":[{"q":"How much does building crack repair cost in Guwahati?","a":"Cosmetic wall crack repair may be a few thousand rupees. Structural column repair with NDT, injection, and CFRP can run lakhs — depends on member count and severity. Inspection first."},{"q":"Should I worry about cracks after a tremor?","a":"New or widening cracks after seismic activity should be inspected before the next season. Guwahati is in India''s highest earthquake zone."},{"q":"Can I sell a flat with column cracks?","a":"Disclosure and structural report affect resale value. NDT before listing gives buyers confidence — or flags work needed before sale."}],"ctaMessage":"Seen a crack? Book structural assessment before monsoon water reaches the steel."}],"inspectionSla":{"headline":"Guwahati inspection SLA","callback":"Same-day phone callback on weekdays (before 4 PM)","visit":"Site visit within 48 hours inside Guwahati city limits","note":"Emergency active leaks — call; we prioritise PU stop-leak when water is entering living spaces."},"diagnosisPack":{"name":"Written Diagnosis Pack","tagline":"What Avicon specs on paper — we give homeowners in plain language.","includes":["Site photos of the problem area","Crack classification: cosmetic vs structural","Moisture / leak path summary (where water is travelling)","Recommended system (membrane, PU, epoxy, CFRP, NDT, or monitor)","Written warranty term for the proposed work","Clear next step: repair now, phased plan, or no action needed"],"ctaLabel":"Book free inspection","ctaHref":"/contact#inspection-form"},"partnerCredentials":{"headline":"Construction chemical systems","intro":"We specify and apply recognised waterproofing and repair systems — not generic acrylic paint.","applicationNote":"Fosroc applicator application in progress. Until approved, we continue with manufacturer-specified systems on every job.","badges":[{"name":"Fosroc","status":"pending","label":"Applicator application in progress"},{"name":"Sika","status":"planned","label":"Planned applicator partnership"},{"name":"Dr. Fixit","status":"systems","label":"Pidilite systems where specified"}]},"portfolioIntro":{"eyebrow":"Executed work","headline":"Before monsoon — after repair","sub":"Six Guwahati jobs: terrace leaks, column cracks, PU injection, and society expansion joints."}}' WHERE slug = 'main';
